export const implicitTasks=[
 {id:'p-exp',family:'scalar',level:0,title:'Eine skalare Gleichung',source:'Originaltyp · B.5.4(a); Lecture Notes 2.21',sourceHref:'#/blaetter/5/B.5.4',purpose:'Nullstelle, passende partielle Ableitung und Ableitungsquotient der Reihe nach prüfen.',intro:R`Sei $F(x,y)=x-3y+e^{xy^2}+2$.`,
 parts:[part(R`Zeige bei $(0,1)$ die lokale Auflösbarkeit $y=g(x)$ und berechne $g'(0)$.`,R`$F(0,1)=0-3+1+2=0$. Die Funktion ist auf $\mathbb R^2$ glatt. Es gilt $$F_x=1+y^2e^{xy^2},\qquad F_y=-3+2xye^{xy^2}.$$`,R`Am Punkt ist $F_y(0,1)=-3\ne0$. Daher existiert lokal eindeutig eine $C^1$-Lösung mit $g(0)=1$.`,R`$$g'(0)=-\frac{F_x(0,1)}{F_y(0,1)}=-\frac2{-3}=\frac23.$$`)],
 questions:[q('Welche Ableitung muss für y = g(x) ungleich null sein?',R`$F_y(0,1)$.`,'Nach der gesuchten Variablen y ableiten; diese Ableitung steht im Nenner.',R`$F_x(0,1)$.`,'Das wäre die Bedingung für die umgekehrte Auflösung x = h(y).',R`$F(0,1)$.`,'Der Funktionswert muss null sein, nicht ungleich null.')],
 hints:[R`Prüfe zuerst $F(0,1)=0$.`,R`Leite $e^{xy^2}$ nach $y$ mit dem inneren Faktor $2xy$ ab.`,R`Setze $F_x=2$, $F_y=-3$ in $-F_x/F_y$ ein.`],fields:[n(R`$g'(0)$`,'2/3')] },
 {...previous('a-implicit'),id:'p-ellipse',family:'scalar',level:1,title:'Beide Auflösungsrichtungen',purpose:'Den Ableitungsquotienten an die tatsächlich gesuchte Variable anpassen.',
 questions:[q(R`Welche Formel gilt für $x=h(y)$?`,R`$h'=-F_y/F_x$.`,'Differenzieren von F(h(y),y)=0 ergibt Fₓ h′ + Fᵧ = 0.',R`$h'=-F_x/F_y$.`,'Diese Formel gehört zu y = g(x).',R`$h'=F_y/F_x$.`,'Beim Umstellen der abgeleiteten Gleichung entsteht ein Minuszeichen.')],
 hints:[R`Am Punkt $(1,2)$ sind $F_x=4$, $F_y=5$.`,R`Beide Ableitungen sind ungleich 0; beide lokalen Auflösungen existieren.`,R`Für die jeweilige gesuchte Variable steht ihre partielle Ableitung im Nenner.`],fields:[n(R`$g'(1)$`,'-4/5'),n(R`$h'(2)$`,'-5/4')] },
 {id:'p-circle',family:'scalar',level:2,title:'Wenn eine Auflösungsrichtung scheitert',source:'Eigene Variante · B.5.4(b); Lecture Notes 2.21',sourceHref:'#/blaetter/5/B.5.4',purpose:'Bei verschwindender partieller Ableitung den Satz korrekt einordnen und die andere Richtung prüfen.',intro:R`Sei $F(x,y)=x^2+y^2-1$ und $a=(1,0)$.`,
 parts:[part(R`Zeige die lokale Auflösbarkeit $x=h(y)$ und berechne $h'(0)$.`,R`$F(1,0)=0$, $F$ ist glatt, und $F_x(1,0)=2\ne0$. Es gibt lokal eindeutig $h$ mit $h(0)=1$ und $$h'(0)=-F_y(1,0)/F_x(1,0)=0.$$ Konkret ist $h(y)=\sqrt{1-y^2}$ nahe 0.`),part(R`Was sagt der Satz zur Auflösung $y=g(x)$? Gibt es hier eine solche Lösung auf einer offenen Umgebung von $x=1$?`,R`Wegen $F_y(1,0)=0$ ist der Satz in dieser Richtung nicht anwendbar. Das allein wäre kein Nichtexistenzbeweis.`,R`Hier ist eine Lösung auf einer offenen Umgebung von 1 tatsächlich unmöglich: Jede solche Umgebung enthält $x>1$, und dort ist $y^2=1-x^2<0$ ohne reelle Lösung.`)],
 questions:[q('Was folgt zunächst aus Fᵧ(1,0) = 0?','Der Satz ist für y = g(x) nicht anwendbar.','Über Existenz oder Nichtexistenz muss dann zusätzlich argumentiert werden.','Es gibt grundsätzlich keine implizite Funktion.','Die andere Auflösungsrichtung funktioniert hier sogar; die Null allein beweist auch in der gewünschten Richtung noch keine Nichtexistenz.','Es gilt g′(1) = 0.','Die Ableitungsformel darf mit Nenner 0 nicht verwendet werden.')],
 hints:[R`Vergleiche $F_x(1,0)$ und $F_y(1,0)$.`,R`Für $x=h(y)$ ist der Nenner 2.`,R`Um $y=g(x)$ wirklich auszuschließen, untersuche $x>1$ nahe 1.`],fields:[n(R`$h'(0)$`,0)] },
 {id:'p-system',family:'system',level:0,title:'Zwei Gleichungen mit einem Parameter',source:'Eigene Variante · Lecture Notes 2.21; B.5.5',sourceHref:'#/blaetter/5/B.5.5',purpose:'Eine vollständige Blockrechnung mit übersichtlichen Zahlen durchführen.',intro:R`Seien $F_1(u,v,t)=u^2+v+t-2$ und $F_2(u,v,t)=u+2v+t^2-3$.`,
 parts:[part(R`Zeige die lokale Auflösung $(u,v)=g(t)$ bei $(1,1,0)$ und berechne $Dg(0)$.`,
 R`Gesucht sind $u,v$ als Funktionen von $t$, also $g(0)=(1,1)$. Prüfe beide Gleichungen: $$F_1(1,1,0)=1+1+0-2=0,\qquad F_2(1,1,0)=1+2+0-3=0.$$ Beide Funktionen sind Polynome, also auf $\mathbb R^3$ glatt.`,
 R`Die Spalten gehören zu $u,v,t$: $$DF(u,v,t)=\begin{pmatrix}2u&1&1\\1&2&2t\end{pmatrix},\qquad DF(1,1,0)=\begin{pmatrix}2&1&1\\1&2&0\end{pmatrix}.$$ Die ersten zwei Spalten ergeben $A=\begin{pmatrix}2&1\\1&2\end{pmatrix}$, die letzte $B=\binom10$.`,
 R`$\det A=2\cdot2-1\cdot1=3\ne0$. Der implizite Funktionensatz liefert die eindeutige lokale $C^1$-Lösung. Für ihre Ableitung invertiere $A$: Diagonale vertauschen, die beiden anderen Vorzeichen wechseln und durch 3 teilen. $$A^{-1}=\frac13\begin{pmatrix}2&-1\\-1&2\end{pmatrix}.$$`,
 R`Verwende $Dg(0)=A^{-1}(-B)$ mit $-B=\binom{-1}0$. Zeile mal Vektor ergibt $$Dg(0)=\frac13\binom{2\cdot(-1)+(-1)\cdot0}{(-1)\cdot(-1)+2\cdot0}=\frac13\binom{-2}1=\binom{-2/3}{1/3}.$$ Somit $u'(0)=-2/3$ und $v'(0)=1/3$.`)],
 questions:[q('Welche Gleichung liefert die Ableitung der Lösung?',R`$A\,Dg=-B$.`,'Sie entsteht durch Differenzieren von F(g(t),t)=0.',R`$A\,Dg=B$.`,'Das Umstellen des freien Ableitungsblocks erzeugt ein Minus.',R`$Dg=-BA^{-1}$.`,'Die Dimensionen passen hier nicht; A multipliziert die Ableitung von links.')],
 hints:[R`Prüfe $F(1,1,0)=(0,0)$.`,R`Der freie Block ist $(1,2t)^T$, am Punkt also $(1,0)^T$.`,R`Invertiere $A$ mit der $2\times2$-Formel. Multipliziere dann $A^{-1}$ mit $-B=(-1,0)^T$.`],fields:[n(R`$u'(0)$`,'-2/3'),n(R`$v'(0)$`,'1/3')] },
 {...original('B.5.5'),id:'p-sheet',family:'system',level:1,title:'Gegebene Ableitungsdaten nutzen',purpose:'Mit unbekannter Funktion und vorgegebenem Df statt einer expliziten Formel arbeiten.',
 questions:[q(R`Welche Daten brauchst du zur Ableitungsrechnung am Punkt?`,'Den Funktionswert zum Nullstellencheck und die ersten Ableitungen am Punkt.','Für den impliziten Satz und Dg genügen die genannten C¹-Voraussetzungen und diese lokalen Daten.','Eine explizite Formel für f auf ganz R².','Die Aufgabe gibt genau die benötigten Daten am Punkt an.','Alle zweiten Ableitungen von f.','Für die erste Ableitung der impliziten Lösung werden nur erste Ableitungen benötigt.')],
 hints:[R`$G(2,-1,1)=0$ und $H(2,-1,1)=0$. Der Wert $f(2,-1)=-1$ wird nur für diesen Nullstellencheck verwendet.`,R`Nach $(x,u)$: $A=\begin{pmatrix}f_x(2,-1)&2\\1&5\end{pmatrix}$. Der freie Block ist $B=(f_y(2,-1),9)^T$.`,R`Erst Teil (b) gibt $Df(2,-1)=(1,-3)$ vor: also $f_x(2,-1)=1$, $f_y(2,-1)=-3$. Invertiere damit $A$ und multipliziere mit $-B=(3,-9)^T$.`],fields:[n(R`$g'(-1)$`,11),n(R`$h'(-1)$`,-4)] },
 {id:'p-exam',family:'system',level:2,title:'Bereinigte Klausuraufgabe 2025',source:'Altklausur 2025, Aufgabe 3(b) · ausdrücklich korrigierte Übungsfassung: +4 in F₁',purpose:'Eine vollständige mehrteilige Klausuranwendung mit Nullstellencheck, Jacobi-Matrix und Lösungsableitung.',intro:R`Verwendet wird die korrigierte Fassung $$F_1(x_1,x_2,y)=-e^{x_1}+2x_2+\cos y+4,\qquad F_2(x_1,x_2,y)=\pi x_1^2+5x_2^3+\sin y+5.$$ Im Klausuroriginal fehlt die $+4$; dann wäre der erste Funktionswert am angegebenen Punkt $-4$ statt 0.`,
 parts:[part(R`Prüfe $F(0,-1,\pi)=0$ und berechne dort $DF$.`,
 R`Setze $x_1=0$, $x_2=-1$, $y=\pi$ in beide korrigierten Gleichungen ein: $$F_1(0,-1,\pi)=-e^0+2(-1)+\cos\pi+4=-1-2-1+4=0,$$ $$F_2(0,-1,\pi)=\pi\cdot0^2+5(-1)^3+\sin\pi+5=0-5+0+5=0.$$ Damit ist der angegebene Punkt tatsächlich eine gemeinsame Nullstelle.`,
 R`Leite jede Ausgabe nach jeder Eingabe ab. Bei $F_1$ liefern $-e^{x_1}$, $2x_2$ und $\cos y$ die Ableitungen $-e^{x_1}$, $2$ und $-\sin y$. Bei $F_2$ liefern $\pi x_1^2$, $5x_2^3$ und $\sin y$ die Ableitungen $2\pi x_1$, $15x_2^2$ und $\cos y$. Alle jeweils anderen Terme sind bei dieser Ableitung konstant.`,
 R`Zeile 1 gehört zu $F_1$, Zeile 2 zu $F_2$; die Spalten stehen in der Reihenfolge $x_1,x_2,y$: $$DF(x_1,x_2,y)=\begin{pmatrix}-e^{x_1}&2&-\sin y\\2\pi x_1&15x_2^2&\cos y\end{pmatrix}.$$ Setze nun den Punkt ein: $$DF(0,-1,\pi)=\begin{pmatrix}-e^0&2&-\sin\pi\\2\pi\cdot0&15(-1)^2&\cos\pi\end{pmatrix}=\begin{pmatrix}-1&2&0\\0&15&-1\end{pmatrix}.$$`),
 part(R`Begründe die lokale Lösung $(x_1,x_2)=g(y)$ mit $g(\pi)=(0,-1)$ und bestimme $Dg(\pi)$.`,
 R`Gesucht sind $x_1=g_1(y)$ und $x_2=g_2(y)$; frei bleibt $y$. Nimm aus der schon berechneten Jacobi-Matrix die Spalten 1 und 2 für $A$, die Spalte 3 für $B$: $$A=\begin{pmatrix}-1&2\\0&15\end{pmatrix},\qquad B=\binom0{-1}.$$`,
 R`$F$ ist auf $\mathbb R^3$ glatt. Der Nullstellencheck wurde in (a) erledigt und $$\det A=(-1)\cdot15-2\cdot0=-15\ne0.$$ Daher gibt es in der Nähe von $y=\pi$ eine eindeutige lokale $C^1$-Lösung mit $g(\pi)=(0,-1)$.`,
 R`Invertiere $A$ mit der $2\times2$-Formel: Tausche die Diagonaleinträge $-1$ und $15$, ändere $2$ zu $-2$ und $0$ bleibt $0$. Teile durch die Determinante $-15$: $$A^{-1}=\frac1{-15}\begin{pmatrix}15&-2\\0&-1\end{pmatrix}=-\frac1{15}\begin{pmatrix}15&-2\\0&-1\end{pmatrix}.$$`,
 R`Die Regel lautet $Dg(\pi)=-A^{-1}B=A^{-1}(-B)$. Zuerst die Vorzeichen in $B$ umdrehen: $-B=-\binom0{-1}=\binom01$. Dann Matrix mal Vektor: $$\begin{pmatrix}15&-2\\0&-1\end{pmatrix}\binom01=\binom{15\cdot0+(-2)\cdot1}{0\cdot0+(-1)\cdot1}=\binom{-2}{-1}.$$`,
 R`Jetzt den Vorfaktor hineinrechnen: $$Dg(\pi)=-\frac1{15}\binom{-2}{-1}=\binom{2/15}{1/15}.$$ Oben steht $g_1'(\pi)=2/15$, unten $g_2'(\pi)=1/15$. Kontrolle: $$A\,Dg(\pi)+B=\binom{-2/15+2/15}{15\cdot(1/15)}+\binom0{-1}=\binom00.$$`)],
 questions:[q('Was prüfst du vor Anwendung des impliziten Satzes?','Ob der angegebene Punkt beide Gleichungen erfüllt.','Die invertierbare Teilmatrix reicht ohne F(a,b)=0 nicht für die geforderte Lösung durch diesen Punkt.','Ob die rechteckige gesamte Jacobi-Matrix eine inverse Matrix hat.','Invertiert wird nur der quadratische Block nach den gesuchten Variablen.','Ob bereits eine explizite Formel für g vorliegt.','Eine solche Formel wird vom impliziten Verfahren gerade nicht vorausgesetzt.')],
 hints:[R`Setze den Punkt zuerst in die korrigierten Funktionen ein.`,R`Für $A$ nimm die Ableitungen nach $(x_1,x_2)$, für $B$ nach $y$.`,R`$\det A=-15$. Invertiere $A$ durch Vertauschen der Diagonale, Vorzeichenwechsel der anderen Einträge und Teilen durch $-15$. Multipliziere danach mit $-B=(0,1)^T$.`],fields:[n(R`$g_1'(\pi)$`,'2/15'),n(R`$g_2'(\pi)$`,'1/15')] },
 {...previous('b-implicit'),id:'p-multifree',family:'multifree',level:0,title:'Zwei freie Variablen',purpose:'Beide Spalten einer Lösungsableitung berechnen statt nur einer Richtung.',
 questions:[q('Welche Form hat Dg, wenn zwei gesuchte von zwei freien Variablen abhängen?','2 Zeilen und 2 Spalten.','Jede Lösungsfunktion bildet eine Zeile, jede freie Variable eine Spalte.','2 Zeilen und 1 Spalte.','Das wäre die Form bei nur einer freien Variablen.','4 Zeilen und 4 Spalten.','Die Ableitung von g enthält nur die zwei Ausgaben von g und die zwei freien Eingaben.')],
 hints:[R`$A=\begin{pmatrix}2&1\\1&2\end{pmatrix}$ hat Determinante 3.`,R`Ableiten nach $(s,t)$ ergibt $B=I_2$.`,R`Invertiere $A$ einmal und verwende $Dg=A^{-1}(-I_2)=-A^{-1}$. Du brauchst nur alle Vorzeichen der inversen Matrix umzudrehen.`],fields:[n(R`$\partial_s g_1(0,0)$`,'-2/3'),n(R`$\partial_t g_1(0,0)$`,'1/3'),n(R`$\partial_s g_2(0,0)$`,'1/3'),n(R`$\partial_t g_2(0,0)$`,'-2/3')] },
 {id:'p-multifree-shift',family:'multifree',level:1,title:'Nichtlinearer Block am verschobenen Punkt',source:'Eigene Variante · Lecture Notes 2.21 und Beispiel 10',purpose:'Am Punkt auswerten und das Minus bei einem negativen freien Block richtig behandeln.',intro:R`Seien $F_1(u,v,s,t)=u+v^2-s$ und $F_2(u,v,s,t)=u^2+v-t$.`,
 parts:[part(R`Zeige die lokale Auflösung $(u,v)=g(s,t)$ bei $(1,1,2,2)$ und bestimme $Dg(2,2)$.`,R`Die Nullstellenprüfung ergibt $F_1(1,1,2,2)=1+1-2=0$ und $F_2(1,1,2,2)=1+1-2=0$. Beide Funktionen sind Polynome und damit glatt.`,R`Gesucht sind $(u,v)$, frei sind $(s,t)$. Somit $$A=\begin{pmatrix}1&2v\\2u&1\end{pmatrix}_{(u,v)=(1,1)}=\begin{pmatrix}1&2\\2&1\end{pmatrix},\qquad B=\begin{pmatrix}-1&0\\0&-1\end{pmatrix}=-I_2.$$ $\det A=1\cdot1-2\cdot2=-3\ne0$. Der Satz liefert lokal eindeutig eine $C^1$-Lösung mit $g(2,2)=(1,1)$.`,R`Invertieren: Diagonale vertauschen, aus beiden Einträgen $2$ wird $-2$, durch $-3$ teilen. $$A^{-1}=\frac1{-3}\begin{pmatrix}1&-2\\-2&1\end{pmatrix}=\begin{pmatrix}-1/3&2/3\\2/3&-1/3\end{pmatrix}.$$`,R`Wegen $-B=I_2$ gilt $$Dg(2,2)=A^{-1}(-B)=A^{-1}I_2=\begin{pmatrix}-1/3&2/3\\2/3&-1/3\end{pmatrix}.$$ Die Zeilen gehören zu $u,v$, die Spalten zu $s,t$. Multiplikation mit $A$ ergibt zur Kontrolle $I_2=-B$.`)],
 questions:[q(R`Was wird aus $-A^{-1}B$, wenn $B=-I_2$?`,R`$A^{-1}$.`,'Die beiden Minuszeichen heben sich auf.',R`$-A^{-1}$.`,'Das Minuszeichen in B wurde dabei übersehen.',R`$A$.`,'Das Vorzeichen ändert sich, die notwendige Matrixinversion bleibt.')],
 hints:[R`Setze den Punkt ein, bevor du $A$ invertierst.`,R`$\det A=1-4=-3$.`,R`Die Ableitungen nach s und t tragen jeweils ein Minuszeichen.`],fields:[n(R`Eintrag $(1,1)$ von $Dg(2,2)$`,'-1/3'),n(R`Eintrag $(1,2)$`,'2/3')] }
];
